// cordis_inspect_query: platform=client, provider=Slots, method=listSubTree
{ "root": "shell.overlay" }      // 应含 { id: "ldw-host", order: 20, active: true }
{ "root": "conversation.view" }  // 应含 { id: "ldw", order: 20, active: true }
```

